"""Tests for scripts/write_sbom.py (#5319 SBOM slice)."""

from __future__ import annotations

import json
import subprocess
from pathlib import Path

import pytest

from scripts.write_sbom import (
    SbomInputError,
    _normalize_git_commit_timestamp,
    build_sbom,
    main,
    parse_npm_lock,
    parse_pip_lock,
)

GIT = ["git"]
PIP_LOCK = """\
# autogenerated
zeta_pkg==2.0.1 ; sys_platform == 'linux' \\
    --hash=sha256:aaaa \\
    --hash=sha256:bbbb
    # via alpha
Alpha==1.2.3
    # via nothing
"""

NPM_LOCK = {
    "name": "fixture",
    "lockfileVersion": 3,
    "packages": {
        "": {"name": "fixture", "version": "1.0.0"},
        "node_modules/left-pad": {"version": "1.3.0", "integrity": "sha1-AAAA"},
        "node_modules/@scope/pkg": {
            "version": "4.5.6",
            "integrity": "sha512-" + "QUJD",
        },
        "node_modules/a/node_modules/linked": {"version": "0.0.1", "link": True},
    },
}


@pytest.fixture
def repo(tmp_path: Path) -> Path:
    (tmp_path / "requirements-docker.lock").write_text(PIP_LOCK, encoding="utf-8")
    (tmp_path / "package-lock.json").write_text(json.dumps(NPM_LOCK), encoding="utf-8")
    git = ["git", "-C", str(tmp_path), "-c", "user.name=t", "-c", "user.email=t@example.invalid"]
    env_date = {"GIT_COMMITTER_DATE": "2026-01-02T03:04:05+00:00", "PATH": _path()}
    subprocess.run([*git, "init", "-q"], check=True)
    subprocess.run([*git, "add", "."], check=True)
    subprocess.run(
        [*git, "commit", "-q", "-m", "init", "--date", "2026-01-02T03:04:05+00:00"],
        check=True,
        env={**env_date, "GIT_AUTHOR_DATE": "2026-01-02T03:04:05+00:00"},
    )
    return tmp_path


def _path() -> str:
    import os

    return os.environ.get("PATH", "")


def _head(repo: Path) -> str:
    return subprocess.run(
        [*GIT, "-C", str(repo), "rev-parse", "HEAD"],
        capture_output=True,
        text=True,
        check=True,
    ).stdout.strip()


@pytest.mark.parametrize(
    ("raw", "expected"),
    [
        ("2026-01-02T03:04:05Z", "2026-01-02T03:04:05Z"),
        ("2026-01-02T03:04:05+00:00", "2026-01-02T03:04:05Z"),
        ("2026-01-02T03:04:05-08:00", "2026-01-02T11:04:05Z"),
    ],
)
def test_normalize_git_commit_timestamp(raw: str, expected: str) -> None:
    assert _normalize_git_commit_timestamp(raw) == expected


def test_sbom_envelope_and_root_component(repo: Path) -> None:
    sbom = build_sbom(repo)
    assert sbom["bomFormat"] == "CycloneDX"
    assert sbom["specVersion"] == "1.5"
    assert sbom["version"] == 1
    root = sbom["metadata"]["component"]
    assert root["type"] == "application"
    assert root["version"] == _head(repo)
    assert sbom["metadata"]["timestamp"] == "2026-01-02T03:04:05Z"


def test_components_have_purls_and_hashes_sorted(repo: Path) -> None:
    comps = build_sbom(repo)["components"]
    purls = [c["purl"] for c in comps]
    assert purls == [
        "pkg:npm/%40scope/pkg@4.5.6",
        "pkg:npm/left-pad@1.3.0",
        "pkg:pypi/alpha@1.2.3",
        "pkg:pypi/zeta-pkg@2.0.1",
    ]
    by_purl = {c["purl"]: c for c in comps}
    assert by_purl["pkg:pypi/zeta-pkg@2.0.1"]["hashes"] == [
        {"alg": "SHA-256", "content": "aaaa"},
        {"alg": "SHA-256", "content": "bbbb"},
    ]
    assert "hashes" not in by_purl["pkg:pypi/alpha@1.2.3"]
    assert by_purl["pkg:npm/%40scope/pkg@4.5.6"]["name"] == "@scope/pkg"
    assert by_purl["pkg:npm/%40scope/pkg@4.5.6"]["hashes"] == [
        {"alg": "SHA-512", "content": "414243"}
    ]
    assert by_purl["pkg:npm/left-pad@1.3.0"]["hashes"][0]["alg"] == "SHA-1"
    assert all(c["bom-ref"] == c["purl"] and c["type"] == "library" for c in comps)


def test_output_is_deterministic(repo: Path, tmp_path_factory: pytest.TempPathFactory) -> None:
    a = tmp_path_factory.mktemp("o") / "a.json"
    b = tmp_path_factory.mktemp("o") / "b.json"
    assert main(["--repo-root", str(repo), "--out", str(a)]) == 0
    assert main(["--repo-root", str(repo), "--out", str(b)]) == 0
    assert a.read_bytes() == b.read_bytes()


def test_check_missing_stale_and_fresh(
    repo: Path, tmp_path_factory: pytest.TempPathFactory
) -> None:
    out = tmp_path_factory.mktemp("o") / "sbom.cdx.json"
    args = ["--repo-root", str(repo), "--out", str(out)]
    assert main([*args, "--check"]) == 1
    assert main(args) == 0
    assert main([*args, "--check"]) == 0
    doc = json.loads(out.read_text(encoding="utf-8"))
    doc["components"].pop()
    out.write_text(json.dumps(doc), encoding="utf-8")
    assert main([*args, "--check"]) == 1


def test_missing_lockfile_raises_clear_error(repo: Path) -> None:
    (repo / "package-lock.json").unlink()
    with pytest.raises(SbomInputError, match="package-lock.json"):
        build_sbom(repo)


def test_malformed_lockfiles_raise_clear_error(repo: Path) -> None:
    (repo / "package-lock.json").write_text("{not json", encoding="utf-8")
    with pytest.raises(SbomInputError, match="package-lock.json"):
        build_sbom(repo)
    (repo / "package-lock.json").write_text(json.dumps(NPM_LOCK), encoding="utf-8")
    (repo / "requirements-docker.lock").write_text("# only comments\n", encoding="utf-8")
    with pytest.raises(SbomInputError, match="requirements-docker.lock"):
        build_sbom(repo)


EXTRAS_LOCK = """\
first==1.0 \\
    --hash=sha256:1111
foo[bar,baz]==2.0 \\
    --hash=sha256:aaaa \\
    --hash=sha256:bbbb
    # via first
marked==3.0 ; python_version > "3.9" \\
    --hash=sha256:cccc
"""


def test_extras_line_is_its_own_component_with_its_own_hashes() -> None:
    by_purl = {c["purl"]: c for c in parse_pip_lock(EXTRAS_LOCK)}
    assert sorted(by_purl) == [
        "pkg:pypi/first@1.0",
        "pkg:pypi/foo@2.0",
        "pkg:pypi/marked@3.0",
    ]
    assert by_purl["pkg:pypi/first@1.0"]["hashes"] == [{"alg": "SHA-256", "content": "1111"}]
    assert [h["content"] for h in by_purl["pkg:pypi/foo@2.0"]["hashes"]] == ["aaaa", "bbbb"]
    assert by_purl["pkg:pypi/foo@2.0"]["name"] == "foo"
    assert by_purl["pkg:pypi/marked@3.0"]["hashes"] == [{"alg": "SHA-256", "content": "cccc"}]


def test_unparseable_requirements_line_raises() -> None:
    with pytest.raises(SbomInputError, match="requirements-docker.lock.*line 2"):
        parse_pip_lock("good==1.0 \\\n    not a requirement\n")


def test_non_dict_npm_package_entry_raises() -> None:
    lock = json.dumps({"packages": {"node_modules/x": "1.0.0"}})
    with pytest.raises(SbomInputError, match="package-lock.json.*node_modules/x"):
        parse_npm_lock(lock)
